import itertools

def get_all_tilings(n):
    cells = [(r, c) for r in range(n) for c in range(n)]

    def is_covered(covered_cells):
        return len(covered_cells) == n*n

    def solve(covered_cells, current_tiling):
        if is_covered(covered_cells):
            yield list(current_tiling)
            return

        # Find the first uncovered cell
        first_cell = None
        for r in range(n):
            for c in range(n):
                if (r, c) not in covered_cells:
                    first_cell = (r, c)
                    break
            if first_cell:
                break

        r, c = first_cell
        # Try all possible dominoes covering this cell
        # 1. Horizontal
        if c + 1 < n and (r, c+1) not in covered_cells:
            covered_cells.add((r, c))
            covered_cells.add((r, c+1))
            current_tiling.append({(r, c), (r, c+1)})
            yield from solve(covered_cells, current_tiling)
            current_tiling.pop()
            covered_cells.remove((r, c+1))
            covered_cells.remove((r, c))

        # 2. Vertical
        if r + 1 < n and (r+1, c) not in covered_cells:
            covered_cells.add((r, c))
            covered_cells.add((r+1, c))
            current_tiling.append({(r, c), (r+1, c)})
            yield from solve(covered_cells, current_tiling)
            current_tiling.pop()
            covered_cells.remove((r+1, c))
            covered_cells.remove((r, c))

    for tiling in solve(set(), []):
        yield tiling

